alter table public.in_app_notifications add column job_id uuid references public.notification_jobs(id) on delete set null;
create unique index notification_once on public.in_app_notifications(job_id) where job_id is not null;
create table public.notification_deliveries(job_id uuid not null references public.notification_jobs(id) on delete cascade,subscription_id uuid not null references public.push_subscriptions(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,state text not null check(state in ('sent','expired','retry','failed')),attempts int not null default 1,last_status int,updated_at timestamptz not null default now(),primary key(job_id,subscription_id));
alter table public.notification_deliveries enable row level security;
revoke all on public.notification_deliveries from public,anon,authenticated;
create policy owner on public.notification_deliveries for select to authenticated using(user_id=auth.uid());grant select on public.notification_deliveries to authenticated;
alter table public.push_subscriptions add constraint endpoint_https check(endpoint like 'https://%');
create function public.schedule_notifications() returns void language plpgsql security definer set search_path='' as $$begin
-- Source changes invalidate old pending work; preferences are checked again at dispatch.
update public.notification_jobs j set state='cancelled' where state in ('pending','retry') and (not exists(select 1 from public.notification_preferences p where p.user_id=j.user_id and p.enabled) or (kind='block' and not exists(select 1 from public.time_blocks b where b.id=j.source_id and b.user_id=j.user_id and b.state='planned' and b.start_at::text=j.payload->>'start_at')) or (kind in ('due_today','due_d1') and not exists(select 1 from public.tasks t where t.id=j.source_id and t.user_id=j.user_id and t.state='open' and t.due_on::text=j.payload->>'due_on')));
insert into public.notification_jobs(user_id,kind,source_id,due_at,idempotency_key,payload)
select b.user_id,'block',b.id,b.start_at-make_interval(mins=>p.event_reminder_minutes),'block:'||b.id||':'||b.start_at::text,jsonb_build_object('start_at',b.start_at::text,'title','일정이 곧 시작돼요','body',p.event_reminder_minutes||'분 후 예정된 일정이 있어요.','week',((b.start_at at time zone pr.timezone)::date-(extract(isodow from b.start_at at time zone pr.timezone)::int-1))::text)
from public.time_blocks b join public.notification_preferences p on b.user_id=p.user_id join public.profiles pr on pr.id=b.user_id where p.enabled and b.state='planned' and b.start_at>now() and b.start_at<now()+interval '8 days' on conflict(user_id,idempotency_key) do nothing;
insert into public.notification_jobs(user_id,kind,source_id,due_at,idempotency_key,payload)
select t.user_id,k.kind,t.id,((t.due_on-k.offset_days)::timestamp+interval '9 hours') at time zone pr.timezone,k.kind||':'||t.id||':'||t.due_on::text,jsonb_build_object('due_on',t.due_on::text,'title',case when k.kind='due_today' then '오늘 마감인 할 일이 있어요' else '내일 마감인 할 일이 있어요' end,'body','플래너에서 마감과 계획을 확인하세요.')
from public.tasks t join public.notification_preferences p on p.user_id=t.user_id join public.profiles pr on pr.id=t.user_id cross join (values('due_today',0),('due_d1',1)) k(kind,offset_days) where p.enabled and t.state='open' and t.due_on between (now() at time zone pr.timezone)::date and (now() at time zone pr.timezone)::date+8 and ((k.kind='due_today' and p.due_today) or(k.kind='due_d1' and p.due_d1)) on conflict(user_id,idempotency_key) do nothing;
insert into public.notification_jobs(user_id,kind,due_at,idempotency_key,payload)
select pr.id,k.kind,((date_trunc('week',now() at time zone pr.timezone)::date+k.days)::timestamp+make_interval(hours=>k.hour)) at time zone pr.timezone,k.kind||':'||date_trunc('week',now() at time zone pr.timezone)::date::text,jsonb_build_object('title',k.title,'body','WEEKFLOW에서 이번 주 흐름을 확인하세요.')
from public.profiles pr join public.notification_preferences p on p.user_id=pr.id cross join (values('review',6,18,'한 주를 돌아볼 시간이에요'),('rollover',0,9,'지난주에 남긴 할 일을 확인하세요')) k(kind,days,hour,title) where p.enabled and ((k.kind='review' and p.weekly_review) or(k.kind='rollover' and p.rollover_prompt)) on conflict(user_id,idempotency_key) do nothing;
end$$;
create function public.claim_notifications(p_limit int default 50) returns setof public.notification_jobs language plpgsql security definer set search_path='' as $$begin
update public.notification_jobs set state='cancelled' where due_at<now()-interval '1 day' and state in ('pending','retry','sending');
return query with ready as (select j.id from public.notification_jobs j join public.notification_preferences p on p.user_id=j.user_id join public.profiles pr on pr.id=j.user_id where j.due_at<=now() and ((j.state in ('pending','retry') and j.updated_at<=now()-case when j.attempts>0 then interval '5 minutes' else interval '0 minutes' end) or (j.state='sending' and j.updated_at<now()-interval '10 minutes')) and j.attempts<5 and p.enabled and (p.quiet_start is null or p.quiet_end is null or p.quiet_start=p.quiet_end or not(case when p.quiet_start<p.quiet_end then (now() at time zone pr.timezone)::time>=p.quiet_start and (now() at time zone pr.timezone)::time<p.quiet_end else (now() at time zone pr.timezone)::time>=p.quiet_start or (now() at time zone pr.timezone)::time<p.quiet_end end)) order by j.due_at for update of j skip locked limit least(greatest(p_limit,1),100)) update public.notification_jobs j set state='sending',attempts=j.attempts+1,updated_at=now() from ready where j.id=ready.id returning j.*;
end$$;
revoke execute on function public.schedule_notifications(),public.claim_notifications(int) from public,anon,authenticated;
grant execute on function public.schedule_notifications(),public.claim_notifications(int) to service_role;
